#include "driver.h"

#include <stdio.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdlib.h>
#include <inttypes.h>
#include <limits.h>
#include <float.h>
#include <math.h>
#include <stdbool.h>
#include <ctype.h>
#include <errno.h>

void printLine(const char *line);

int main(void)
{
    int case_no = 1;
    int d;

    printf("case %d: direct printLine\n", case_no++);
    printLine("hello");
    printLine("");
    printLine(NULL);

    /*
     * The surviving mutants are the "100" that sizes `dest`
     * (`char dest[100] = "";`) and the "100"/"1" inside
     * `source[100-1] = '\0';`, which places source's null terminator.
     * Both only matter for calls that take the `data < 100` branch, and
     * only become observable once `data` gets close to the buffer's
     * real capacity (dest gets truncated one byte earlier/later than
     * before, or an out-of-bounds write is reached at a different
     * `data` value than the unmutated code needs). The previous driver
     * only probed a handful of isolated points (0, 1, 50, 99) in that
     * range, which left room for an off-by-a-few-bytes mutation to slip
     * through untested. Sweeping every `data` value from 0 through 99
     * guarantees that whatever exact boundary a mutation shifts these
     * constants to, some case in this sweep sits right on it.
     */
    for (d = 0; d < 100; d++) {
        printf("case %d: driver(%d)\n", case_no++, d);
        driver(d);
    }

    printf("case %d: driver(100)\n", case_no++);
    driver(100);

    printf("case %d: driver(101)\n", case_no++);
    driver(101);

    printf("case %d: driver(1000)\n", case_no++);
    driver(1000);

    printf("case %d: driver(INT_MAX)\n", case_no++);
    driver(INT_MAX);

    printf("case %d: driver(0) again\n", case_no++);
    driver(0);

    printf("case %d: driver(99) again\n", case_no++);
    driver(99);

    return 0;
}
